enum kPacketNumberSpace {
  Initial,
  Handshake,
  ApplicationData,
}

OnAckReceived(ack, pn_space):
  if (largest_acked_packet[pn_space] == infinite):
    largest_acked_packet[pn_space] = ack.largest_acked
  else:
    largest_acked_packet[pn_space] =
        max(largest_acked_packet[pn_space], ack.largest_acked)

  // Nothing to do if there are no newly acked packets.
  newly_acked_packets = DetermineNewlyAckedPackets(ack, pn_space)
  if (newly_acked_packets.empty()):
    return

  // If the largest acknowledged is newly acked and
  // at least one ack-eliciting was newly acked, update the RTT.
  if (sent_packets[pn_space].contains(ack.largest_acked) &&
      IncludesAckEliciting(newly_acked_packets)):
    latest_rtt =
      now - sent_packets[pn_space][ack.largest_acked].time_sent
    ack_delay = 0
    if (pn_space == ApplicationData):
      ack_delay = ack.ack_delay
    UpdateRtt(ack_delay)

  // Process ECN information if present.
  if (ACK frame contains ECN information):
      ProcessECN(ack, pn_space)

  for acked_packet in newly_acked_packets:
    OnPacketAcked(acked_packet.packet_number, pn_space)

  DetectLostPackets(pn_space)

  pto_count = 0

  SetLossDetectionTimer()


UpdateRtt(ack_delay):
  // First RTT sample.
  if (smoothed_rtt == 0):
    min_rtt = latest_rtt
    smoothed_rtt = latest_rtt
    rttvar = latest_rtt / 2
    return

  // min_rtt ignores ack delay.
  min_rtt = min(min_rtt, latest_rtt)
  // Limit ack_delay by max_ack_delay
  ack_delay = min(ack_delay, max_ack_delay)
  // Adjust for ack delay if plausible.
  adjusted_rtt = latest_rtt
  if (latest_rtt > min_rtt + ack_delay):
    adjusted_rtt = latest_rtt - ack_delay

  rttvar = 3/4 * rttvar + 1/4 * abs(smoothed_rtt - adjusted_rtt)
  smoothed_rtt = 7/8 * smoothed_rtt + 1/8 * adjusted_rtt

// Returns the earliest loss_time and the packet number // space it's from. Returns 0 if all times are 0. GetEarliestLossTime(): time = loss_time[Initial] space = Initial for pn_space in [ Handshake, ApplicationData ]: if (loss_time[pn_space] != 0 && (time == 0 || loss_time[pn_space] < time)): time = loss_time[pn_space]; space = pn_space return time, space
PeerNotAwaitingAddressValidation(): # Assume clients validate the server's address implicitly. if (endpoint is server): return true # Servers complete address validation when a # protected packet is received. return has received Handshake ACK || has received 1-RTT ACK
SetLossDetectionTimer(): loss_time, _ = GetEarliestLossTime() if (loss_time != 0): // Time threshold loss detection. loss_detection_timer.update(loss_time) return
if (no ack-eliciting packets in flight && PeerNotAwaitingAddressValidation()): loss_detection_timer.cancel() return
// Use a default timeout if there are no RTT measurements if (smoothed_rtt == 0): timeout = 2 * kInitialRtt else: // Calculate PTO duration timeout = smoothed_rtt + max(4 * rttvar, kGranularity) + max_ack_delay timeout = timeout * (2 ^ pto_count)
loss_detection_timer.update( time_of_last_sent_ack_eliciting_packet + timeout)

OnLossDetectionTimeout():
  loss_time, pn_space = GetEarliestLossTime()
  if (loss_time != 0):
    // Time threshold loss Detection
    DetectLostPackets(pn_space)
    SetLossDetectionTimer()
    return

  if (endpoint is client without 1-RTT keys):
    // Client sends an anti-deadlock packet: Initial is padded
    // to earn more anti-amplification credit,
    // a Handshake packet proves address ownership.
    if (has Handshake keys):
      SendOneAckElicitingHandshakePacket()
    else:
      SendOneAckElicitingPaddedInitialPacket()
  else:
    // PTO. Send new data if available, else retransmit old data.
    // If neither is available, send a single PING frame.
    SendOneOrTwoAckElicitingPackets()

  pto_count++
  SetLossDetectionTimer()

DetectLostPackets(pn_space):
  assert(largest_acked_packet[pn_space] != infinite)
  loss_time[pn_space] = 0
  lost_packets = {}
  loss_delay = kTimeThreshold * max(latest_rtt, smoothed_rtt)

  // Minimum time of kGranularity before packets are deemed lost.
  loss_delay = max(loss_delay, kGranularity)

  // Packets sent before this time are deemed lost.
  lost_send_time = now() - loss_delay

  foreach unacked in sent_packets[pn_space]:
    if (unacked.packet_number > largest_acked_packet[pn_space]):
      continue

    // Mark packet as lost, or set time when it should be marked.
    if (unacked.time_sent <= lost_send_time ||
        largest_acked_packet[pn_space] >=
          unacked.packet_number + kPacketThreshold):
      sent_packets[pn_space].remove(unacked.packet_number)
      if (unacked.in_flight):
        lost_packets.insert(unacked)
    else:
      if (loss_time[pn_space] == 0):
        loss_time[pn_space] = unacked.time_sent + loss_delay
      else:
        loss_time[pn_space] = min(loss_time[pn_space],
                                  unacked.time_sent + loss_delay)

  // Inform the congestion controller of lost packets and
  // let it decide whether to retransmit immediately.
  if (!lost_packets.empty()):
    OnPacketsLost(lost_packets)

InCongestionRecovery(sent_time):
  return sent_time <= congestion_recovery_start_time

OnPacketAckedCC(acked_packet):
  // Remove from bytes_in_flight.
  bytes_in_flight -= acked_packet.size
  if (InCongestionRecovery(acked_packet.time_sent)):
    // Do not increase congestion window in recovery period.
    return
  if (IsAppLimited()):
    // Do not increase congestion_window if application
    // limited.
    return
  if (congestion_window < ssthresh):
    // Slow start.
    congestion_window += acked_packet.size
  else:
    // Congestion avoidance.
    congestion_window += kMaxDatagramSize * acked_packet.size
        / congestion_window

CongestionEvent(sent_time):
  // Start a new congestion event if packet was sent after the
  // start of the previous congestion recovery period.
  if (!InCongestionRecovery(sent_time)):
    congestion_recovery_start_time = Now()
    congestion_window *= kLossReductionFactor
    congestion_window = max(congestion_window, kMinimumWindow)
    ssthresh = congestion_window

ProcessECN(ack, pn_space):
  // If the ECN-CE counter reported by the peer has increased,
  // this could be a new congestion event.
  if (ack.ce_counter > ecn_ce_counters[pn_space]):
    ecn_ce_counters[pn_space] = ack.ce_counter
    CongestionEvent(sent_packets[ack.largest_acked].time_sent)

InPersistentCongestion(largest_lost_packet):
  pto = smoothed_rtt + max(4 * rttvar, kGranularity) +
    max_ack_delay
  congestion_period = pto * kPersistentCongestionThreshold
  // Determine if all packets in the time period before the
  // newest lost packet, including the edges, are marked
  // lost
  return AreAllPacketsLost(largest_lost_packet,
                           congestion_period)

OnPacketsLost(lost_packets):
  // Remove lost packets from bytes_in_flight.
  for (lost_packet : lost_packets):
    bytes_in_flight -= lost_packet.size
  largest_lost_packet = lost_packets.last()
  CongestionEvent(largest_lost_packet.time_sent)

  // Collapse congestion window if persistent congestion
  if (InPersistentCongestion(largest_lost_packet)):
    congestion_window = kMinimumWindow
